    action udp_forward(macAddr_t dstAddr, egressSpec_t port) {
        standard_metadata.egress_spec = port;
        hdr.ethernet.srcAddr = hdr.ethernet.dstAddr;
        hdr.ethernet.dstAddr = dstAddr;
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
    }

    table ipv4_lpm {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            ipv4_forward;
            udp_forward;
            drop;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    table udp_multicast {
        key = {
            hdr.ipv4.dstAddr : lpm;
            hdr.udp.dstPort : exact;
        }
        actions = {
            udp_forward;
            NoAction;
        }
        size = 1024;
        default_action = drop();
    }

    table nat_table {
        key = {
            hdr.ipv4.srcAddr : exact;
            hdr.ipv4.dstAddr : exact;
        }
        actions = {
            modify_field(hdr.ipv4.srcAddr, meta.nat_mapping[0]);
            modify_field(hdr.ipv4.dstAddr, meta.nat_mapping[1]);
            NoAction;
        }
        size = 1024;
        default_action = NoAction();
    }

    apply {
        if (hdr.ipv4.isValid() && hdr.udp.isValid()) {
            nat_table.apply();
            if (hdr.ipv4.dstAddr == 0xFFFFFFFF) { // Multicast address
                udp_multicast.apply();
            } else {
                ipv4_lpm.apply();
            }
        }
    }
