    apply {
        if (meta.nat_mapping[0] != 0) {
            modify_field(hdr.ipv4.srcAddr, meta.nat_mapping[0]);
        }
        if (meta.nat_mapping[1] != 0) {
            modify_field(hdr.ipv4.dstAddr, meta.nat_mapping[1]);
